package io.knowledgebrain.gateway;
import java.net.http.*;import java.util.*;import org.junit.jupiter.api.*;import org.springframework.mock.web.MockHttpServletRequest;
import org.springframework.web.server.ResponseStatusException;import io.micrometer.core.instrument.simple.SimpleMeterRegistry;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class GroupProxyTest {
 GatewayTransport transport;GatewayController proxy;String root="/api/groups",id="01a10000-0000-7000-8000-000000000000";
 @BeforeEach @SuppressWarnings("unchecked") void init()throws Exception{transport=mock(GatewayTransport.class);proxy=new GatewayController(transport,new SimpleMeterRegistry(),"https://localhost:8443");HttpResponse<byte[]> response=mock(HttpResponse.class);when(response.statusCode()).thenReturn(200);when(response.body()).thenReturn("{}".getBytes());when(response.headers()).thenReturn(HttpHeaders.of(Map.of("Content-Type",List.of("application/json")),(a,b)->true));when(transport.send(any(),anyString(),anyMap(),any())).thenReturn(response);}
 MockHttpServletRequest request(String method,String path){var r=new MockHttpServletRequest(method,path);r.setSecure(true);r.addHeader("Origin","https://localhost:8443");r.setContentType("application/json");return r;}
 @Test void exactCreateIntentAndCookieForwardedWithoutCallerAuthority()throws Exception{var r=request("POST",root);r.addHeader("Idempotency-Key","a".repeat(32));r.addHeader("Cookie","__Host-brain_guest="+"b".repeat(43));r.addHeader("Authorization","Bearer forged");r.addHeader("X-Principal-Id",id);r.setContent("{}".getBytes());proxy.proxy(r);verify(transport).send(eq(new GatewayRoute("collaboration",root)),eq("POST"),argThat(h->h.get("Idempotency-Key").equals(List.of("a".repeat(32)))&&h.containsKey("Cookie")&&!h.containsKey("Authorization")&&!h.containsKey("X-Principal-Id")),eq("{}".getBytes()));}
 @Test void missingDuplicateKeysAndOversizedBodyAreRejected(){var missing=request("POST",root);assertThrows(ResponseStatusException.class,()->proxy.proxy(missing));var duplicate=request("POST",root);duplicate.addHeader("Idempotency-Key","a".repeat(32));duplicate.addHeader("Idempotency-Key","b".repeat(32));assertThrows(ResponseStatusException.class,()->proxy.proxy(duplicate));var oversized=request("POST",root);oversized.setContent(new byte[65537]);assertEquals(413,assertThrows(ResponseStatusException.class,()->proxy.proxy(oversized)).getStatusCode().value());verifyNoInteractions(transport);}
 @Test void boundedQueriesReadBodiesAndWriteQueriesAreRejected(){for(String query:List.of("limit=101","limit=0","limit=20&limit=20","ownerId="+id,"after="+id.toUpperCase(),"after=../bad")){var r=request("GET",root);r.setQueryString(query);assertThrows(ResponseStatusException.class,()->proxy.proxy(r));}var detail=request("GET",root+"/"+id);detail.setQueryString("limit=1");assertThrows(ResponseStatusException.class,()->proxy.proxy(detail));var read=request("GET",root);read.setContent("{}".getBytes());assertThrows(ResponseStatusException.class,()->proxy.proxy(read));var write=request("POST",root);write.setQueryString("limit=1");assertThrows(ResponseStatusException.class,()->proxy.proxy(write));verifyNoInteractions(transport);}
 @Test void validHistoryAndCompletionDoNotForwardCreateKey()throws Exception{var history=request("GET",root+"/"+id+"/revisions");history.setQueryString("before=2&limit=1");proxy.proxy(history);verify(transport).send(eq(new GatewayRoute("collaboration",root+"/"+id+"/revisions?before=2&limit=1")),eq("GET"),anyMap(),any());var completion=request("POST",root+"/"+id+"/complete");completion.addHeader("Idempotency-Key","a".repeat(32));proxy.proxy(completion);verify(transport).send(eq(new GatewayRoute("collaboration",root+"/"+id+"/complete")),eq("POST"),argThat(h->!h.containsKey("Idempotency-Key")),any());}
}
